  delivery_phone TEXT NULL,
  void_reason TEXT NULL,
  voided_at TEXT NULL,
  order_date TEXT NOT NULL,
  completed_at TEXT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT NULL,
  sync_version INTEGER NOT NULL DEFAULT 0,
  device_id TEXT NULL,
  sync_status TEXT NOT NULL DEFAULT 'PENDING' CHECK (sync_status IN ('PENDING','SYNCED','CONFLICT','FAILED')),
  CHECK (order_type IN ('DINE_IN','TAKEAWAY','DELIVERY')),
  CHECK (source IN ('POS','WEB','PHONE')),
  CHECK (status IN ('DRAFT','HELD','OPEN','IN_KITCHEN','READY','SERVED','BILLED','COMPLETED','VOIDED','CANCELLED')),
  CHECK (payment_status IN ('UNPAID','PARTIAL','PAID','REFUNDED','PARTIAL_REFUND')),
  CHECK (discount_type IN ('NONE','PERCENT','FIXED','COUPON')),
  FOREIGN KEY (table_uuid) REFERENCES restaurant_tables(uuid),
  FOREIGN KEY (customer_uuid) REFERENCES customers(uuid),
  FOREIGN KEY (waiter_uuid) REFERENCES users(uuid),
  FOREIGN KEY (cashier_uuid) REFERENCES users(uuid),
  FOREIGN KEY (coupon_uuid) REFERENCES coupons(uuid),
  FOREIGN KEY (parent_order_uuid) REFERENCES orders(uuid),
  FOREIGN KEY (voided_by_uuid) REFERENCES users(uuid),
  FOREIGN KEY (branch_uuid) REFERENCES branches(uuid)
);
