-- ---------------------------------------------------------------------------
-- Local-only tables
-- ---------------------------------------------------------------------------
CREATE TABLE sync_outbox (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  local_id        TEXT    NOT NULL UNIQUE,            -- uuid of this outbox entry
  entity_type     TEXT    NOT NULL,                   -- table name, e.g. 'orders'
  entity_uuid     TEXT    NOT NULL,
  operation       TEXT    NOT NULL CHECK (operation IN ('CREATE','UPDATE','DELETE')),
  payload_json    TEXT    NOT NULL,
  base_version    INTEGER NOT NULL DEFAULT 0,         -- server sync_version this edit was based on
  created_at      TEXT    NOT NULL,
  updated_at      TEXT    NOT NULL,
  retry_count     INTEGER NOT NULL DEFAULT 0,
  status          TEXT    NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','SYNCING','SYNCED','FAILED','CONFLICT')),
  error_message   TEXT    NULL,
  last_attempt_at TEXT    NULL,
  next_attempt_at TEXT    NULL,                       -- exponential backoff
  batch_id        TEXT    NULL
);
CREATE INDEX ix_outbox_status ON sync_outbox (status, next_attempt_at);
CREATE INDEX ix_outbox_entity ON sync_outbox (entity_type, entity_uuid);
CREATE INDEX ix_outbox_batch  ON sync_outbox (batch_id);

CREATE TABLE sync_state (
  state_key   TEXT PRIMARY KEY,                       -- device_id, last_pull_at, api_base_url ...
  state_value TEXT NULL,
  updated_at  TEXT NOT NULL
);

CREATE TABLE sync_log (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  occurred_at TEXT NOT NULL,
  level       TEXT NOT NULL CHECK (level IN ('INFO','WARN','ERROR')),
  direction   TEXT NOT NULL CHECK (direction IN ('PUSH','PULL','SYSTEM')),
  batch_id    TEXT NULL,
  message     TEXT NOT NULL,
  details     TEXT NULL
);
CREATE INDEX ix_sync_log_time ON sync_log (occurred_at);

CREATE TABLE sync_conflicts_local (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  entity_type    TEXT NOT NULL,
  entity_uuid    TEXT NOT NULL,
  local_json     TEXT NOT NULL,
  server_json    TEXT NULL,
  reason         TEXT NULL,
  status         TEXT NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','RESOLVED')),
  detected_at    TEXT NOT NULL,
  resolved_at    TEXT NULL
);

CREATE TABLE app_meta (
  meta_key   TEXT PRIMARY KEY,
  meta_value TEXT NULL
);
